#include <stdio.h>
int main() {
  //创建数组
  int arr[10];//这个10表示数组的长度是10，即数组中元素的个数是10，数组的长度是固定的，不能改变
  //赋值  可以不连续赋值
  arr[0] = 1;//这里的0表示数组的下标，数组的下标是从0开始的，最大下标是数组长度-1
  arr[3] = 5;//同理
  arr[5] = 10;//同理
  //访问数据
  printf("arr[0]的值: %d\n", arr[0]);
  printf("arr[3]的值: %d\n", arr[3]);
  printf("arr[5]的值: %d\n", arr[5]);
  //循环的方式访问数组
  for (int i = 0; i < 10; i++)
  {
    printf("arr[%d]的值: %d\n", i, arr[i]);//没有赋值的下标，访问的结果是随机的，因为没有赋值，所以访问的是其他内存空间的数据
  }
  //1 无论是赋值还是访问，都是通过下标的方式进行的，数组的下标是从0开始的，最大下标是数组长度-1
  //2 而且数组的下标是从0开始的
  //3 访问数组时，如果访问的下标超过了数组的最大下标，程序不会报错，但是会访问到其他内存空间的数据，可能会导致程序崩溃
  //~~~~~~~
  //~~~~~~~
  //arr[10] = 100; //访问数组的下标超过了数组的最大下标9，程序不会报错，但是会访问到其他内存空间的数据，可能会导致程序崩溃
  //printf("arr[10]的值: %d\n", arr[10]); //访问数组的下标超过了数组的最大下标9，访问的结果也不是自己想要的，可能会导致程序崩溃
  return 0;
}